from tenders import T, calc, breakeven, SALT, LAST
MAIN=["0118100005726000082","0360100026226000404","0368200010326000024","0351100004326000111",
      "0118300007926000015","0368300000126001453","0131300000626001316","0164300016526000498","32616449090",
      "0848300058126000318"]
def f(x): return f"{x:,.0f}".replace(","," ")
by={t["id"]:t for t in T}
def verdict(t):
    b=calc(t,t["disc"][1])["net"]; be=breakeven(t)
    if b<=0: return "**Нет**"
    if be<0.35: return "Осторожно"
    return "**Участвовать**"
def row(i,t):
    r0=calc(t,0); rb=calc(t,t["disc"][1]); rw=calc(t,t["disc"][2]); C=sum(t["cost"].values())+t["log"]
    return (f"| {i} | {t['grp']} | [{t['id']}]({t['src']}) {t['name']}<br>{t['cust']} | {t['deadline']} | {f(t['nmck'])} | {f(C)} | "
            f"{r0['gm']*100:.0f}% / {f(r0['net'])} | −{t['disc'][1]*100:.0f}% → {f(rb['P'])} | {rb['gm']*100:.0f}% / **{f(rb['net'])}** | "
            f"−{t['disc'][2]*100:.0f}% → {f(rw['net'])} | {breakeven(t)*100:.0f}% | {verdict(t)} |")
H=("| № | Группа | Закупка | Подача | НМЦК, ₽ | Себестоимость с доставкой, ₽ | При НМЦК: валовая маржа / прибыль | Ожидаемое снижение → цена, ₽ | При ожидаемой цене: маржа / прибыль | Худший сценарий: прибыль | Безубыточно до снижения | Решение |\n"
   "|---|---|---|---|---|---|---|---|---|---|---|---|")
out=["# Оценка маржи по 10 открытым закупкам (на 10.10.2026)","",
"**Как считали.** ООО на УСН 15% без НДС. Цена контракта = НМЦК × (1 − снижение). Себестоимость — цены поставщиков с НДС: на УСН входящий НДС не вычитается и идёт в расходы. Сверху: банк, ЭТП и гарантия — 0,8% цены, деньги в обороте — 20% годовых за цикл поставки, налог — 15% от разницы доходов и расходов. «Прибыль» ниже — это прибыль после налога на одну сделку, без общих расходов компании (зарплаты, аренды и т. п.). Модель: [`model/tenders.py`](model/tenders.py).","",
"**Откуда цифры.** Закупки, позиции и цены за единицу взяты из открытого зеркала ЕИС (gosplan), портала закупок Московской области (easuz.mosreg) и bicotender. Ожидаемое снижение цены — медианы по завершённым аналогичным закупкам (протоколы gosplan). ТЗ и проекты контрактов скачать не удалось: zakupki.gov.ru недоступен. Поэтому перед подачей заявки обязательно сверить ТЗ, сроки поставки и оплаты. Пометка [Г] — гипотеза.","",
f"**Соль.** Себестоимость {SALT} ₽/т — данные клиента: казахстанская соль в МКР, НДС включён, с доставкой в РФ. Если в эту цену не входит доставка до склада заказчика, прибыль ниже, см. таблицу «Соль: чувствительность».","",
"## 10 закупок","",H]
for i,k in enumerate(MAIN,1): out.append(row(i,by[k]))
out+=["","## Соль: чувствительность к доставке до заказчика (+{} ₽/т) [Г]".format(f(LAST)),"","| Закупка | Тонн | Прибыль при ожидаемом снижении −15%, ₽ | То же с доставкой +1 000 ₽/т, ₽ |","|---|---|---|---|"]
for t in T:
    if "tons" in t:
        t2=dict(t); t2["cost"]={"x":t["tons"]*(SALT+LAST)}
        out.append(f"| {t['id']} {t['cust']} | {t['tons']} | {f(calc(t,t['disc'][1])['net'])} | {f(calc(t2,t['disc'][1])['net'])} |")
out+=["","## Себестоимость по позициям","",]
for k in MAIN:
    t=by[k]; out.append(f"**{t['id']} — {t['name']}** ({t['law']})")
    for n,v in t["cost"].items(): out.append(f"- {n}: {f(v)} ₽")
    out.append(f"- Доставка: {f(t['log'])} ₽"); out.append("")
out+=["## Дополнительно рассчитанные закупки (не вошли в 10)","",H]
for i,t in enumerate([t for t in T if t["id"] not in MAIN],1): out.append(row(i,t))
out+=["","## Выводы","",
"1. **Техническая соль из Казахстана — главный актив.** Пять открытых лотов дают 0,4–2,2 млн ₽ прибыли каждый при обычном снижении. В ноль выходим, только если цену снизят на 60–70%. На аукционе можно опуститься ниже любого конкурента, который закупает соль в РФ по 5–7 тыс. ₽/т. Что проверить до подачи:",
"   - паспорт качества: NaCl ≥96,5%, помол № 3, галит типа С;",
"   - упаковка: МКР или биг-бэг;",
"   - доставку до склада заказчика;",
"   - в Ульяновске обеспечение исполнения 30%.",
"2. **ПГМ в мешках** (Мосгортур, Тамбов). Цена в закупке 54–61 тыс. ₽/т при себестоимости 20–45 тыс. ₽/т. Главный риск — соответствие ТЗ: число компонентов, прочность гранул, воздействие на обувь. Нужен паспорт производителя под ТЗ.",
"3. **Силовые заказчики (МЧС).** Шлемы и палатки дают 28–30% маржи при обычном снижении, СИЗ с особыми требованиями (Саратов) — 43%. Форменная одежда невыгодна: на торгах цену снижают примерно на 40%, а розница выше НМЦК. Работать с формой можно только с прямой ценой швейного производителя.",
"4. **Счётчики с установкой** (Дубна) выгодны, если найти монтажника по ~2 500 ₽ за точку [Г].",
"5. **Не участвуем:** кирзовые сапоги, AGM-аккумуляторы, дезсредства без прайса производителя под ТЗ, таблетированная соль через трейдера, форменные костюмы по рознице.",
"6. **Светильники для школ Москвы** — только с дилерской ценой производителя из реестра (CSVT, ЭРА, ЛучСмарт) примерно на 30% ниже цен контрактов-аналогов: снижение в похожих закупках 30–60%.",
]
open("../TENDERS_10.md","w",encoding="utf-8").write("\n".join(out)+"\n")
